INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind mehr vCPUs immer besser für eine VM?', 2, '[{"text": "Nein", "correct": true, "because": "Overhead kann Leistung senken"}, {"text": "Ja", "correct": false, "because": "Nicht universell vorteilhaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressource wähle ich für eine rechenintensive VM?', 3, '[{"text": "Hohe vCPU", "correct": true, "because": "Mehr Rechenleistung"}, {"text": "Wenig vRAM", "correct": false, "because": "RAM auch wichtig"}, {"text": "Geringe Bandbreite", "correct": false, "because": "Netzwerk sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen vRAM für Datenbanken entscheidend?', 5, '[{"text": "Schneller Datenzugriff", "correct": true, "because": "Daten im Speicher halten"}, {"text": "Hohe Kapazität", "correct": true, "because": "Große Datenmengen verarbeiten"}, {"text": "Geringer Bedarf", "correct": false, "because": "Mehr RAM besser"}, {"text": "Einfache Zuweisung", "correct": false, "because": "Leistung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) vCPUs entsprechen physischen Kernen. b) vRAM beeinflusst die VM-Leistung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist falsch, virtuell zugewiesen"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Ressourcenzuweisung für eine Webserver-VM?', 4, '[{"text": "vCPU-Anzahl", "correct": false, "because": "Wichtig für Anfragen"}, {"text": "vRAM-Größe", "correct": false, "because": "Beeinflusst Antwortzeit"}, {"text": "Lokale Grafikleistung", "correct": true, "because": "Irrelevant für Webserver"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob zu viel vRAM die Performance senkt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur ungenutzt, kein direkter Schaden"}, {"text": "Ja", "correct": false, "because": "Overhead minimal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für eine VM mit hoher Last?', 3, '[{"text": "Hohe vCPU-Zahl", "correct": true, "because": "Parallele Verarbeitung"}, {"text": "Minimale vRAM", "correct": false, "because": "RAM auch nötig"}, {"text": "Einfache Verwaltung", "correct": false, "because": "Leistung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine hohe vCPU-Zuweisung?', 5, '[{"text": "Mehr Rechenleistung", "correct": true, "because": "Parallele Aufgaben"}, {"text": "Bessere Multitasking", "correct": true, "because": "Mehr Threads"}, {"text": "Geringere Latenz", "correct": false, "because": "Nicht direkt"}, {"text": "Einfachere Verwaltung", "correct": false, "because": "Komplexität steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) vRAM ist wichtiger als vCPU. b) Zu viele vCPUs verlangsamen. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "a) nicht immer"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine VM mit geringer Last?', 4, '[{"text": "Moderate vCPU", "correct": false, "because": "Ausreichend für Basis"}, {"text": "Angemessenes vRAM", "correct": false, "because": "Für Betrieb nötig"}, {"text": "Maximale vCPU-Zahl", "correct": true, "because": "Überdimensioniert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Beeinflusst vRAM die CPU-Leistung?', 2, '[{"text": "Nein", "correct": true, "because": "Unabhängige Ressourcen"}, {"text": "Ja", "correct": false, "because": "Nur indirekt bei Engpässen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für eine Rendering-VM entscheidend?', 4, '[{"text": "Hohe vCPU", "correct": true, "because": "Parallele Berechnungen"}, {"text": "Großes vRAM", "correct": true, "because": "Daten im Speicher"}, {"text": "Geringe Bandbreite", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass mehr vCPUs immer schneller sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Overprovisioning kann schaden"}, {"text": "Ja", "correct": false, "because": "Nicht linear"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für eine VM mit Datenanalyse?', 3, '[{"text": "Großes vRAM", "correct": true, "because": "Daten im Speicher halten"}, {"text": "Wenige vCPUs", "correct": false, "because": "Rechenleistung nötig"}, {"text": "Einfache Konfiguration", "correct": false, "because": "Leistung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) vCPU-Zuweisung ist flexibel. b) vRAM ist unwichtig für kleine VMs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, RAM immer relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine Überzuweisung von vCPUs?', 5, '[{"text": "Performanceverlust", "correct": true, "because": "Wettbewerb um physische Kerne"}, {"text": "Höherer Overhead", "correct": true, "because": "Mehr Verwaltung"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht vorteilhaft"}, {"text": "Einfachere Skalierung", "correct": false, "because": "Komplexer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer VM für Office-Anwendungen unwichtig?', 3, '[{"text": "Moderate vRAM", "correct": false, "because": "Für Betrieb nötig"}, {"text": "Ausreichende vCPU", "correct": false, "because": "Grundlast abdecken"}, {"text": "Extreme vCPU-Zahl", "correct": true, "because": "Übertrieben für Office"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist vRAM für VMs teurer als vCPU?', 3, '[{"text": "Nein", "correct": true, "because": "Kosten hardwareabhängig"}, {"text": "Ja", "correct": false, "because": "Keine feste Regel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob mehr vRAM die Latenz senkt?', 2, '[{"text": "Nein", "correct": true, "because": "Latenz netzwerkabhängig"}, {"text": "Ja", "correct": false, "because": "Nur indirekt hilfreich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressourcen wähle ich für eine VM mit Videostreaming?', 4, '[{"text": "Moderate vCPU, hohes vRAM", "correct": true, "because": "Buffering und Verarbeitung"}, {"text": "Hohe vCPU, wenig vRAM", "correct": false, "because": "RAM für Daten nötig"}, {"text": "Minimale Ressourcen", "correct": false, "because": "Unzureichend"}]');
